     3	export function signedDifferenceInDays(fromDate, toDate) {
     4	  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / (1000 * 60 * 60 * 24))
     5	}
     6	
     7	export function beginningOfDay(date) {
     8	  const { year, month, day } = datePartsInTimezone(date)
     9	  return new Date(Date.UTC(year, month - 1, day))
    10	}
    11	
    12	// Snap a timestamp to midnight using the timezone the server rendered with (the
    13	// `timezone` meta tag), so client day boundaries match the server's instead of
    14	// following the browser's resolved timezone, which can differ in a PWA.
    15	function datePartsInTimezone(date) {
    16	  return dateFormatter().formatToParts(date).reduce((parts, { type, value }) => {
    17	    if (type !== "literal") parts[type] = parseInt(value, 10)
    18	    return parts
    19	  }, {})
    20	}
    21	
    22	let dateFormatterCache
    23	let dateFormatterTimezone
    24	
    25	function dateFormatter() {
    26	  const timezone = getMetaContent("timezone")
    27	
    28	  if (!dateFormatterCache || dateFormatterTimezone !== timezone) {
    29	    dateFormatterTimezone = timezone
    30	    dateFormatterCache = buildDateFormatter(timezone)
    31	  }
    32	
    33	  return dateFormatterCache
    34	}
    35	
    36	function buildDateFormatter(timezone) {
    37	  const options = { year: "numeric", month: "2-digit", day: "2-digit" }
    38	
    39	  try {
    40	    return new Intl.DateTimeFormat("en-US", { ...options, timeZone: timezone })
    41	  } catch {
    42	    return new Intl.DateTimeFormat("en-US", options)
    43	  }
    44	}
