const MILLISECONDS_PER_MINUTE = 60_000
const MILLISECONDS_PER_HOUR = 60 * MILLISECONDS_PER_MINUTE
const MILLISECONDS_PER_DAY = 24 * MILLISECONDS_PER_HOUR
const RECENT_DAY_LIMIT = 6

const dateTimeFormatters = new Map()
const relativeDayFormatter = new Intl.RelativeTimeFormat("en-US", { numeric: "auto" })
const relativeTimeFormatter = new Intl.RelativeTimeFormat("en-US", { numeric: "always" })

export function formatLocalTime(date, format = "date-time", now = new Date()) {
  switch (format) {
  case "contextual":
    return formatContextualDate(date, now)
  case "date":
    return formatDate(date, now)
  case "date-time":
    return formatDateTime(date)
  case "date-with-year":
    return formatDateWithYear(date)
  case "long-date":
    return formatLongDate(date, now)
  case "relative":
    return formatRelativeDate(date, now)
  case "time":
    return formatTime(date)
  case "time-ago":
    return formatTimeAgo(date, now)
  default:
    throw new Error(`Unknown local time format: ${format}`)
  }
}

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MILLISECONDS_PER_DAY)
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

function formatContextualDate(date, now) {
  if (signedDifferenceInDays(now, date) === 0) {
    return formatTime(date)
  } else {
    return formatRelativeDate(date, now)
  }
}

function formatRelativeDate(date, now) {
  const days = signedDifferenceInDays(now, date)

  if (Math.abs(days) <= RECENT_DAY_LIMIT) {
    return relativeDayFormatter.format(days, "day")
  } else {
    return formatDate(date, now)
  }
}

function formatTimeAgo(date, now) {
  const difference = date - now
  const absoluteDifference = Math.abs(difference)

  if (absoluteDifference < MILLISECONDS_PER_MINUTE) {
    return difference > 0 ? "in a moment" : "just now"
  } else if (absoluteDifference < MILLISECONDS_PER_HOUR) {
    return relativeTimeFormatter.format(Math.round(difference / MILLISECONDS_PER_MINUTE), "minute")
  } else if (absoluteDifference < MILLISECONDS_PER_DAY) {
    return relativeTimeFormatter.format(Math.round(difference / MILLISECONDS_PER_HOUR), "hour")
  } else {
    return formatTimeAgoInDays(date, now, difference)
  }
}

function formatTimeAgoInDays(date, now, difference) {
  const days = signedDifferenceInDays(now, date)

  if (Math.abs(days) < 30) {
    return relativeTimeFormatter.format(days, "day")
  } else if (Math.abs(days) < 365) {
    return relativeTimeFormatter.format(Math.round(difference / (30 * MILLISECONDS_PER_DAY)), "month")
  } else {
    return relativeTimeFormatter.format(Math.round(difference / (365 * MILLISECONDS_PER_DAY)), "year")
  }
}

function formatDate(date, now) {
  const options = { month: "short", day: "numeric" }
  if (date.getFullYear() !== now.getFullYear()) options.year = "numeric"

  return dateTimeFormatter(options).format(date)
}

function formatDateWithYear(date) {
  return dateTimeFormatter({ year: "numeric", month: "short", day: "numeric" }).format(date)
}

function formatLongDate(date, now) {
  const options = { weekday: "long", month: "long", day: "numeric" }
  if (date.getFullYear() !== now.getFullYear()) options.year = "numeric"

  return dateTimeFormatter(options).format(date)
}

function formatDateTime(date) {
  return dateTimeFormatter({
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit"
  }).format(date)
}

function formatTime(date) {
  return dateTimeFormatter({ hour: "numeric", minute: "2-digit" }).format(date)
}

function dateTimeFormatter(options) {
  const key = JSON.stringify(options)

  if (!dateTimeFormatters.has(key)) {
    dateTimeFormatters.set(key, new Intl.DateTimeFormat("en-US", options))
  }

  return dateTimeFormatters.get(key)
}
