import { Controller } from "@hotwired/stimulus"
import { patch } from "@rails/request.js"

export default class extends Controller {
  static values = { updateUrl: String }

  connect() {
    this.#updateTimezone()
  }

  #updateTimezone() {
    const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone

    if (timezone !== this.#timezoneCookie) {
      document.cookie = `timezone=${encodeURIComponent(timezone)}; path=/; SameSite=Lax`
      this.#updateUserTimezone(timezone)
    }
  }

  #updateUserTimezone(timezone) {
    if (this.hasUpdateUrlValue && window.Current.user) {
      patch(this.updateUrlValue, { body: { timezone_name: timezone } })
    }
  }

  get #timezoneCookie() {
    const cookie = document.cookie.split("; ").find(cookie => cookie.startsWith("timezone="))
    return cookie ? decodeURIComponent(cookie.split("=").slice(1).join("=")) : null
  }
}
JS

